import { ResponseError } from "../../errors.js";
import { EMPTY_BUFFER } from "../../protocol/definitions.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  JoinGroup Request (Version: 0) => group_id session_timeout_ms member_id protocol_type [protocols]
    group_id => STRING
    session_timeout_ms => INT32
    member_id => STRING
    protocol_type => STRING
    protocols => name metadata
      name => STRING
      metadata => BYTES
*/
export function createRequest(groupId, sessionTimeoutMs, _rebalanceTimeoutMs, memberId, _groupInstanceId, protocolType, protocols, _reason) {
    return Writer.create()
        .appendString(groupId, false)
        .appendInt32(sessionTimeoutMs)
        .appendString(memberId, false)
        .appendString(protocolType, false)
        .appendArray(protocols, (w, protocol) => w.appendString(protocol.name, false).appendBytes(protocol.metadata ?? EMPTY_BUFFER, false), false, false);
}
/*
  JoinGroup Response (Version: 0) => error_code generation_id protocol_name leader member_id [members]
    error_code => INT16
    generation_id => INT32
    protocol_name => STRING
    leader => STRING
    member_id => STRING
    members => member_id metadata
      member_id => STRING
      metadata => BYTES
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const response = {
        throttleTimeMs: 0,
        errorCode: reader.readInt16(),
        generationId: reader.readInt32(),
        protocolType: null,
        protocolName: reader.readString(false),
        leader: reader.readString(false),
        skipAssignment: false,
        memberId: reader.readString(false),
        members: reader.readArray(r => ({ memberId: r.readString(false), groupInstanceId: null, metadata: r.readBytes(false) }), false, false)
    };
    if (response.errorCode !== 0) {
        throw new ResponseError(apiKey, apiVersion, { '/': [response.errorCode, null] }, response);
    }
    return response;
}
export const api = createAPI(11, 0, createRequest, parseResponse, false, false);
